//! Linker-provided symbols. The linker script is generated by `build.zig`, so
//! these are the only cross-boundary names between build and kernel.

pub extern var __kernel_start: u8;
pub extern var __kernel_end: u8;
pub extern var __text_start: u8;
pub extern var __text_end: u8;
pub extern var __rodata_start: u8;
pub extern var __rodata_end: u8;
pub extern var __data_start: u8;
pub extern var __data_end: u8;
pub extern var __bss_start: u8;
pub extern var __bss_end: u8;

pub fn addr(sym: *anyopaque) usize {
    return @intFromPtr(sym);
}

pub fn kernelRange() struct { start: usize, end: usize } {
    return .{ .start = @intFromPtr(&__kernel_start), .end = @intFromPtr(&__kernel_end) };
}

pub fn imageSize() usize {
    const r = kernelRange();
    return r.end - r.start;
}
